\begin{aligned}
\operatorname{Sublanguage}_{17}(L,L')\leftrightarrow{}&
\mathrm{Var}_L=\mathrm{Var}_{L'}\land\mathrm{Log}_L=\mathrm{Log}_{L'}
\land\mathrm{Const}_L\subseteq\mathrm{Const}_{L'}\\
&\land\forall n\in\omega\;
\bigl(\mathrm{Func}_{L,n}\subseteq\mathrm{Func}_{L',n}
\land\mathrm{Rel}_{L,n}\subseteq\mathrm{Rel}_{L',n}\bigr),\\
\operatorname{Sublanguage}_{17}(L,L')\to{}&
\Bigl(\operatorname{Reduct}_{L',L}(\mathfrak B)
\coloneqq(B,\mathcal J\upharpoonright\operatorname{Sym}(L))\Bigr),\\
\operatorname{Sublanguage}_{17}(L,L')\to{}&
\Bigl(\mathfrak B\upharpoonright L\coloneqq\operatorname{Reduct}_{L',L}(\mathfrak B)\Bigr),\\
\operatorname{Sublanguage}_{17}(L,L')\to{}&
\mathfrak B\upharpoonright L\in\mathrm{Structure}(L).
\end{aligned}
